/* Reset margin and padding */
.mw-content-ltr ul.bp-css-grid p,
.mw-content-ltr ul.bp-css-grid {
  margin: 0;
  padding: 0;
}

.mw-content-ltr ul.grid-autofit {
  display: grid;
  grid-template-columns: 1fr;
  grid-gap: 2rem;
  list-style: none;
}

@media (min-width: 576px) {
  .mw-content-ltr ul.grid-autofit {
    grid-template-columns: repeat(auto-fit, minmax(var(--min), 1fr));
  }

.bp-side .bp-card-component {
    display: flex;
    flex-direction: initial;
}
}


.bp-card-component > :not(.card-image-container) {
  text-wrap: pretty;
}

.card-actions a {
  transition: all 0.3s ease;
}

/** vars **/
.bp-card-component {
  --img-ratio: 3/2;
}

.bp-card-component > .card-image-container > img {
  aspect-ratio: var(--img-ratio);
}

.mw-content-ltr ul.bp-css-grid.DISABLED {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(var(--min), 1fr));
    gap: var(--gap);
    justify-content: center;
    max-width: calc(var(--columns) * var(--min) + (var(--columns) - 1) * var(--gap));
    align-content: center;
    align-items: center;
    margin: 2rem 1rem;
}

/* ===== Base grid (shared) ===== */
.mw-content-ltr ul.bp-css-grid {
  display: grid;
  gap: var(--gap, 2rem);
  list-style: none;
  padding: 0;
  margin: 2rem 1rem;
}

/* ===== Mode: AUTO (flexible, stretch to container) ===== */
.mw-content-ltr ul.bp-css-grid.bp-auto-grid {
  grid-template-columns: repeat(auto-fit, minmax(var(--min, 30ch), 1fr));
  max-width: none;          /* ensure no cap in auto mode */
  justify-content: stretch; /* columns fill the row */
}

/* ===== Mode: CENTERED (N columns, centered block) =====
   Expects --columns to be set inline (the module sets it when mode=centered).
   We cap the UL to the exact width of N tracks + gaps, then center the UL.
   Tracks inside still use auto-fit so they gracefully drop columns on narrow viewports. */
.mw-content-ltr ul.bp-css-grid.bp-center-grid {
  grid-template-columns: repeat(auto-fit, minmax(var(--min, 30ch), 1fr));
  max-width: calc(var(--columns, 2) * var(--min, 30ch) + (var(--columns, 2) - 1) * var(--gap, 2rem));
  margin-left: auto;
  margin-right: auto;
  justify-content: center;  /* tidy up subpixel slack */
}

/* Keep these AFTER the old rules. */
.mw-content-ltr ul.bp-css-grid.bp-auto-grid.grid-autofit { max-width: none; }
.mw-content-ltr ul.bp-css-grid.bp-center-grid.grid-autofit {
  max-width: calc(var(--columns, 2) * var(--min, 30ch) + (var(--columns, 2) - 1) * var(--gap, 2rem));
}

