document.addEventListener("DOMContentLoaded", function() {
    // Check if the script has already been executed
    if (window.bpcardsClickable) {
        return; // Exit the function if the script has already run
    }

    // Set the flag to true to prevent re-execution
    window.bpcardsClickable = true;

    // Select clickable items from both lists
    var clickableItems = document.querySelectorAll('li.clickable');

    clickableItems.forEach(function(item) {
        // Direct clicks on the item itself
        item.addEventListener('click', function(event) {
            navigateAccordingToDataUrl(item, event);
        });

        // Handle keyboard interactions
        item.addEventListener('keydown', function(event) {
            if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                navigateAccordingToDataUrl(item, event);
            }
        });
    });

function navigateAccordingToDataUrl(item, event) {
    // Prevent the default action to handle navigation manually
    event.preventDefault();

    var url = item.getAttribute('data-url');
    if (url) {
        // Handle URLs with fragments (e.g., #tab1 or #some-anchor)
        if (url.startsWith('#')) {
            const hash = url.substring(1); // Remove the '#' character
            const anchorElement = document.getElementById(hash);

            if (anchorElement) {
                // Check if the anchor is a tab panel or inside a tab panel
                const isTabPanel = anchorElement.classList.contains('bp-panel-content');
                const isInsideTabPanel = anchorElement.closest('.bp-panel-content') !== null;

                if (isTabPanel || isInsideTabPanel) {
                    // If the anchor is a tab panel or inside a tab, use openTabAndScroll
                    openTabAndScroll(hash, true);
                } else {
                    // If the anchor is not inside a tab, scroll directly to it
                    setTimeout(function () {
                        anchorElement.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    }, 200);
                }
            } else {
                // If no matching anchor is found, set the hash normally
                window.location.hash = '#' + hash;
            }
        } else if (url.startsWith('http')) {
            // Navigate to the URL in the same tab (full URL)
            window.location.href = url;
        } else {
            // Prepend '/' to the URL and navigate in the same tab (relative URL)
            window.location.href = '/' + url;
        }
    }
}
